// Local HTTPS MITM proxy so static-PHP's OpenSSL ClientHello (blocked by the
// sandbox transparent proxy) can reach the internet via Node's TLS stack.
const http = require('http');
const tls = require('tls');
const net = require('net');
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const CERT_DIR = path.join(__dirname, 'certs');
const CA_CRT = path.join(CERT_DIR, 'ca.crt');
const CA_KEY = path.join(CERT_DIR, 'ca.key');
const LEAF_DIR = path.join(CERT_DIR, 'leaves');
fs.mkdirSync(LEAF_DIR, { recursive: true });

function mintLeaf(host) {
  const safe = host.replace(/[^a-zA-Z0-9._-]/g, '_');
  const key = path.join(LEAF_DIR, safe + '.key');
  const crt = path.join(LEAF_DIR, safe + '.crt');
  if (fs.existsSync(crt) && fs.existsSync(key)) return { key, crt };
  const csr = path.join(LEAF_DIR, safe + '.csr');
  const ext = path.join(LEAF_DIR, safe + '.ext');
  fs.writeFileSync(ext, `subjectAltName=DNS:${host}\nextendedKeyUsage=serverAuth\n`);
  execFileSync('openssl', ['req', '-newkey', 'rsa:2048', '-nodes', '-keyout', key,
    '-out', csr, '-subj', `/CN=${host}`], { stdio: 'ignore' });
  execFileSync('openssl', ['x509', '-req', '-in', csr, '-CA', CA_CRT, '-CAkey', CA_KEY,
    '-CAcreateserial', '-out', crt, '-days', '3650', '-extfile', ext], { stdio: 'ignore' });
  fs.unlinkSync(csr);
  fs.unlinkSync(ext);
  return { key, crt };
}

const server = http.createServer((req, res) => {
  // Plain HTTP proxying (rare for composer, but handle it).
  const url = new URL(req.url);
  const upstream = net.connect(80, url.hostname, () => {
    upstream.write(`${req.method} ${url.pathname}${url.search} HTTP/1.1\r\n` +
      `Host: ${url.host}\r\nConnection: close\r\n`);
    rawHead(req, upstream, res);
  });
  upstream.on('error', () => res.destroy());
});

function rawHead(req, upstream, res) {
  // skip first line + host, rebuild in caller instead
}

server.on('connect', (req, clientSocket, head) => {
  const [host, port] = req.url.split(':');
  const targetPort = parseInt(port || '443', 10);

  // 1. TLS connection from client (PHP) to us, presenting minted leaf cert.
  // 2. TLS connection from us to the real target (Node TLS works in sandbox).
  let leaf;
  try { leaf = mintLeaf(host); }
  catch (e) { clientSocket.destroy(); return; }

  const serverTlsSocket = new tls.TLSSocket(clientSocket, {
    isServer: true,
    key: fs.readFileSync(leaf.key),
    cert: fs.readFileSync(leaf.crt),
    CA: fs.readFileSync(CA_CRT),
  });

  serverTlsSocket.on('error', () => clientSocket.destroy());

  serverTlsSocket.on('secure', () => {
    const upstream = tls.connect({ host, port: targetPort, servername: host }, () => {
      clientSocket.write('HTTP/1.1 200 Connection Established\r\n\r\n');
      if (head && head.length) upstream.write(head);
      serverTlsSocket.pipe(upstream);
      upstream.pipe(serverTlsSocket);
    });
    upstream.on('error', () => { try { serverTlsSocket.destroy(); } catch (_) {} });
  });
});

const PORT = process.env.MITM_PORT ? parseInt(process.env.MITM_PORT, 10) : 8899;
server.listen(PORT, '127.0.0.1', () => {
  console.log(`MITM proxy listening on http://127.0.0.1:${PORT}`);
});

